let storageAvailable = true;
function readSaved(key) {
 try {
  const value = JSON.parse(localStorage.getItem(key) || '{}');
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
 } catch { storageAvailable = false; return {}; }
}
const savedDecisions = readSaved(storageKey);
const savedNotes = readSaved(notesKey);
let decisions = Object.fromEntries(Object.entries(savedDecisions).filter(([id,value]) => schoolById.has(id) && ['good','bad'].includes(value)));
let notes = Object.fromEntries(Object.entries(savedNotes).filter(([id,value]) => schoolById.has(id) && typeof value === 'string').map(([id,value]) => [id,value.slice(0,10000)]));
let history = [];
let busy = false;
let drag = null;
let displayedPhoto = null;
let currentSchool = null;
let editingNoteId = null;
let photoTimer;
let photoRequest = 0;
function save() {
 try {
  localStorage.setItem(storageKey,JSON.stringify(decisions));
  localStorage.setItem(notesKey,JSON.stringify(notes));
  storageAvailable = true;
 } catch { storageAvailable = false; }
 showSaveStatus();
 return storageAvailable;
}
function showSaveStatus() {
 get('save-status').textContent = storageAvailable ? 'Lists and notes stay in this browser. Download a copy to keep a backup.' : 'Browser storage is unavailable or full. Download lists + notes before closing to keep your changes.';
}
function announce(message) { get('announcement').textContent = message; }
function optionalNumber(id) {
 const input=get(id); const raw=input.value.trim();
 return raw !== '' && Number.isFinite(Number(raw)) && Number(raw)>=0 ? Number(raw) : null;
}
function filtersFromUI() {
 return {query:normalizeSearch(get('search').value),field:get('field').value,sizeEnabled:get('size-enabled').checked,sizeMax:Number(get('size-max').value),citations:optionalNumber('citations'),employment:optionalNumber('employment'),averageSalary:optionalNumber('average-salary'),tuition:get('tuition-enabled').checked?optionalNumber('tuition'):null,tuitionBasis:get('tuition-basis').value,living:get('living-enabled').checked?optionalNumber('living'):null,international:optionalNumber('international'),includeUnknown:get('include-unknown').checked};
}
function numericMatch(value,limit,direction,includeUnknown) {
 if (limit === null) return true;
 if (value === null || value === undefined) return includeUnknown;
 return direction === 'min' ? value >= limit : value <= limit;
}
const knownCities = new Set(universities.map(u=>normalizeSearch(u.city)));
function matchesSearch(u,query) {
 if(!query)return true;
 const state=Object.entries(stateNames).find(([code,name])=>query===code.toLowerCase() || query===normalizeSearch(name));
 if(state)return u.state===state[0];
 const suffix=Object.entries(stateNames).find(([code,name])=>query.endsWith(' '+code.toLowerCase()) || query.endsWith(' '+normalizeSearch(name)));
 let rest=query;
 if(suffix){
  if(u.state!==suffix[0])return false;
  const ending=query.endsWith(' '+suffix[0].toLowerCase())?suffix[0].toLowerCase():normalizeSearch(suffix[1]);
  rest=query.slice(0,-ending.length).trim();
 }
 if(knownCities.has(rest))return normalizeSearch(u.city)===rest;
 return rest.split(/\s+/).every(term=>searchIndex.get(u.id).includes(term));
}
function matchesUniversity(u,f) {
 if(!matchesSearch(u,f.query))return false;
 if (f.field && !u.fields.includes(f.field)) return false;
 if (f.sizeEnabled && !numericMatch(u.size,f.sizeMax,'max',f.includeUnknown)) return false;
 return numericMatch(u.citations,f.citations,'min',f.includeUnknown) && numericMatch(u.employment,f.employment,'min',f.includeUnknown) && numericMatch(u.averageSalary,f.averageSalary,'min',f.includeUnknown) && numericMatch(u[f.tuitionBasis],f.tuition,'max',f.includeUnknown) && numericMatch(u.living,f.living,'max',f.includeUnknown) && numericMatch(u.international,f.international,'min',f.includeUnknown);
}
function matchingSchools() { const f=filtersFromUI(); return universities.filter(u => matchesUniversity(u,f)); }
function remaining() { return matchingSchools().filter(u => !decisions[u.id]); }
function setBusyControls() {
 for (const input of get('filters').querySelectorAll('input,select,button')) input.disabled=busy;
 get('tuition').disabled=busy || !get('tuition-enabled').checked;
 get('living').disabled=busy || !get('living-enabled').checked;
 get('size-max').disabled=busy || !get('size-enabled').checked;
 for (const id of ['search','clear-search','reset','reset-empty','note']) get(id).disabled=busy;
 get('undo').disabled=busy || !history.length;
 for(const type of ['good','bad'])get(`clear-${type}`).disabled=busy || !Object.values(decisions).includes(type);
 get('clear-notes').disabled=busy || !Object.keys(notes).length;
 get('bad-button').disabled=busy || !currentSchool;
 get('good-button').disabled=busy || !currentSchool;
}
function showCampusPhoto(u,force=false) {
 if (displayedPhoto===u.id && !force) return;
 displayedPhoto=u.id;
 const request=++photoRequest;
 clearTimeout(photoTimer);
 const slot=get('photo-slot');slot.replaceChildren();
 const message=get('photo-message');message.hidden=false;
 const credit=get('photo-credit');credit.hidden=!u.photo;
 const attribution=get('photo-attribution');attribution.textContent='';attribution.title='';
 get('campus').dataset.kind=u.photoKind || 'campus';get('photo-type').hidden=u.photoKind!=='logo';
 const retry=get('retry-photo');retry.hidden=true;
 if(!u.photo){message.textContent='A verified photo is not available for this school yet. Find campus views on its official website below.';return;}
 const [url,source,alt,filePage]=u.photo;
 const image=document.createElement('img');image.id='campus-photo';image.alt=alt;image.draggable=false;image.decoding='async';image.referrerPolicy='no-referrer';image.hidden=true;
 message.textContent='Loading school photo…';
 credit.href=filePage || source;
 credit.textContent=filePage?'Photo source & license ↗':`Photo source: ${u.group==='University of California'?'University of California':u.name} ↗`;
 if(u.photoCredit){attribution.textContent=`${u.photoCredit.author} · ${u.photoCredit.license}`;attribution.title=u.photoCredit.author;}
 const active=()=>request===photoRequest;
 const failed=()=>{if(!active())return;message.hidden=false;message.textContent='The photo host is taking too long or is unavailable. You can retry or use the official website below.';retry.hidden=false;};
 let triedFallback=false;
 image.addEventListener('load',()=>{if(!active())return;clearTimeout(photoTimer);image.hidden=false;message.hidden=true;retry.hidden=true;});
 image.addEventListener('error',()=>{
  if(!active())return;
  clearTimeout(photoTimer);image.hidden=true;
  if(u.photoFallback && !triedFallback){triedFallback=true;image.src=u.photoFallback;photoTimer=setTimeout(failed,12000);}
  else failed();
 });
 slot.append(image);image.src=url;photoTimer=setTimeout(failed,12000);
}
get('retry-photo').addEventListener('click',()=>{if(currentSchool && !busy)showCampusPhoto(currentSchool,true);});

function addFact(label,value) {
 const div=document.createElement('div'); const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=value;div.append(dt,dd);return div;
}
function renderCard() {
 const matches=matchingSchools();const queue=matches.filter(u=>!decisions[u.id]);const u=queue[0] || null;currentSchool=u;
 get('progress-text').textContent=`${number(matches.length)} matching · ${number(queue.length)} left to review`;
 get('progress-bar').style.width=matches.length ? `${(matches.length-queue.length)/matches.length*100}%` : '0%';
 get('card').hidden=!u;get('complete').hidden=!!u;get('card-notes').hidden=!u;
 if(u) {
  get('university-name').textContent=u.name;
  get('location').textContent=`${u.city}, ${stateNames[u.state] || u.state}`;
  get('school-group').textContent=u.group;
  get('description').textContent=u.graduate ? 'A graduate-focused institution. Undergraduate measures may not apply; check the official website for degrees and admissions.' : `Compare ${u.name} with your priorities, then keep a note of what stands out.`;
  showCampusPhoto(u);
  const tags=u.highlights.map(([code,share])=>{const tag=document.createElement('span');tag.textContent=`${fieldNames[code]} · ${(share*100).toFixed(1)}%`;return tag;});
  if(!tags.length){const tag=document.createElement('span');tag.textContent='Undergraduate program highlights not reported';tags.push(tag);}
  get('tags').replaceChildren(...tags);
  const basis=get('tuition-basis').value;
  get('school-facts').replaceChildren(addFact('Undergraduate enrollment',number(u.size)),addFact('International undergraduates',u.international==null?'Not reported':`${number(u.international)}%`),addFact(`${basis==='tuitionIn'?'In-state':'Out-of-state'} tuition + fees / year`,money(u[basis])),addFact(`${u.livingBasis || 'Annual'} living expenses / year`,money(u.living)),addFact('Scientific citations · OpenAlex total',number(u.citations)),addFact('Employment rate · tracked cohort',u.employment==null?'Not reported':`${number(u.employment)}%`),addFact('Average annual earnings · historical',money(u.averageSalary)));
  const f=filtersFromUI();const missing=[];
  if(f.includeUnknown)for(const [key,label,active] of [['size','enrollment',f.sizeEnabled],[f.tuitionBasis,'tuition',f.tuition!==null],['living','living expenses',f.living!==null],['international','international share',f.international!==null],['citations','citations',f.citations!==null],['employment','employment rate',f.employment!==null],['averageSalary','average earnings',f.averageSalary!==null]])if(active && u[key]==null)missing.push(label);
  get('missing-data').textContent=missing.length?`Included with missing data: ${missing.join(', ')}. These filter limits could not be verified.`:'Figures are from the June 2026 Scorecard release; reporting years vary. Research snapshot: September 2026.';
  get('school-link').href=u.url;get('data-link').href=`https://collegescorecard.ed.gov/school/?${u.unitid}`;
  get('research-link').hidden=!u.researchUrl;if(u.researchUrl)get('research-link').href=u.researchUrl;
  get('note').value=notes[u.id] || '';get('note').dataset.schoolId=u.id;
  get('note').setAttribute('aria-label',`My notes about ${u.name}`);
  get('note-status').textContent=notes[u.id]? (storageAvailable?'Note saved in this browser.':'Note is only in memory. Download a backup.') : 'Notes save as you type.';
 }else{
  get('complete-title').textContent=matches.length?'You’ve reviewed these matches.':'No universities match yet.';
  get('summary').textContent=matches.length?'Your choices are in the lists below. Undo a choice, remove a school from a list to review it again, or change your filters.':'Try a broader field, raise a budget, or include schools with missing data.';
 }
 setBusyControls();
}
function noteCount(){return Object.values(notes).filter(value=>value.trim()).length;}
function updateNoteIndicators(){get('clear-notes').disabled=busy || !Object.keys(notes).length;get('notes-count').textContent=`${number(noteCount())} schools`;get('notes-empty').hidden=noteCount()>0 || !!editingNoteId;}
function storeNote(id,value) {
 if(!schoolById.has(id))return;
 if(value)notes[id]=value.slice(0,10000);else delete notes[id];
 const ok=save();updateNoteIndicators();
 for(const area of document.querySelectorAll('textarea[data-school-id]')) if(area.dataset.schoolId===id && area!==document.activeElement)area.value=notes[id] || '';
 for(const preview of document.querySelectorAll('[data-note-preview]'))if(preview.dataset.notePreview===id)preview.textContent=notes[id] || '';
 get('note-status').textContent=ok?'Note saved in this browser.':'Could not save to browser storage. Download a backup.';
}
function renderNotebook(){
 const schools=universities.filter(u=>notes[u.id]?.trim() || u.id===editingNoteId);
 get('notebook-list').replaceChildren(...schools.map(u=>{
  const item=document.createElement('li');const label=document.createElement('label');label.htmlFor=`note-${u.id}`;label.textContent=u.name;
  const area=document.createElement('textarea');area.id=label.htmlFor;area.dataset.schoolId=u.id;area.rows=3;area.maxLength=10000;area.value=notes[u.id] || '';area.placeholder='Your thoughts about this university…';area.addEventListener('input',()=>storeNote(u.id,area.value));
  const small=document.createElement('small');small.textContent=`${u.city}, ${u.state} · ${decisions[u.id] ? `${decisions[u.id]} list` : 'Not sorted yet'}`;
  item.append(label,small,area);return item;
 }));updateNoteIndicators();
}
function openNotes(u){editingNoteId=u.id;document.querySelector('.notebook').open=true;renderNotebook();get(`note-${u.id}`).focus();}
function renderLists(){
 get('saved-count').textContent=Object.keys(decisions).length;
 for(const type of ['bad','good']){
  const list=universities.filter(u=>decisions[u.id]===type);get(`${type}-count`).textContent=list.length;get(`${type}-empty`).hidden=!!list.length;
  get(`${type}-list`).replaceChildren(...list.map(u=>{
   const item=document.createElement('li');const link=document.createElement('a');link.href=u.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=u.name;
   const small=document.createElement('small');small.textContent=`${u.city}, ${u.state}`;
   const preview=document.createElement('p');preview.className='list-note-preview';preview.dataset.notePreview=u.id;preview.textContent=notes[u.id] || '';
   const actions=document.createElement('div');actions.className='list-actions';
   for(const [label,action] of [[`Move to ${type==='good'?'bad':'good'}`,()=>change(u.id,type==='good'?'bad':'good')],['Remove',()=>change(u.id,null)],['Notes',()=>openNotes(u)]]){
    const button=document.createElement('button');button.textContent=label;button.setAttribute('aria-label',`${label}: ${u.name}`);button.addEventListener('click',()=>{if(!busy)action();});actions.append(button);
   }
   item.append(link,small,preview,actions);return item;
  }));
 }
}
function render(){renderCard();renderLists();renderNotebook();showSaveStatus();}
function change(id,type){
 if(busy || !schoolById.has(id))return;
 history.push({id,previous:decisions[id]});if(type)decisions[id]=type;else delete decisions[id];save();render();
 announce(`${schoolById.get(id).name} ${type ? `added to your ${type} list` : 'returned to the review deck'}.`);
}
async function choose(type){
 if(!currentSchool || busy || drag)return;
 const u=currentSchool;busy=true;setBusyControls();
 const card=get('card');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 card.style.transition=reduced?'none':'transform .22s ease, opacity .22s ease';card.style.transform=`translateX(${type==='good'?100:-100}%) rotate(${type==='good'?12:-12}deg)`;card.style.opacity='0';
 await new Promise(resolve=>setTimeout(resolve,reduced?0:230));
 busy=false;resetDrag();change(u.id,type);
 if(!currentSchool)get('undo').focus();
}
function resetDrag(){drag=null;const card=get('card');card.classList.remove('dragging');card.style.transition='';card.style.transform='';card.style.opacity='';get('swipe-label').textContent='';}
get('card').addEventListener('pointerdown',event=>{
 if(busy || !currentSchool || event.button!==0 || !event.isPrimary || event.target.closest('a,button,input,select,textarea,summary'))return;
 drag={id:event.pointerId,x:event.clientX,y:event.clientY,dx:0,dy:0};get('card').setPointerCapture(event.pointerId);get('card').classList.add('dragging');
});
get('card').addEventListener('pointermove',event=>{
 if(!drag || drag.id!==event.pointerId)return;drag.dx=event.clientX-drag.x;drag.dy=event.clientY-drag.y;
 if(Math.abs(drag.dx)<Math.abs(drag.dy))return;
 get('card').style.transform=`translateX(${drag.dx}px) rotate(${drag.dx/25}deg)`;get('swipe-label').textContent=Math.abs(drag.dx)>25?(drag.dx>0?'GOOD LIST →':'← BAD LIST'):'';
});
get('card').addEventListener('pointerup',event=>{if(!drag || drag.id!==event.pointerId)return;const {dx,dy}=drag;resetDrag();if(Math.abs(dx)>=Math.min(90,get('card').offsetWidth*.22) && Math.abs(dx)>Math.abs(dy))choose(dx>0?'good':'bad');});
get('card').addEventListener('pointercancel',resetDrag);
get('card').addEventListener('lostpointercapture',()=>{if(drag)resetDrag();});
get('bad-button').addEventListener('click',()=>choose('bad'));get('good-button').addEventListener('click',()=>choose('good'));
get('undo').addEventListener('click',()=>{if(busy || !history.length)return;const last=history.pop();if(last.previous)decisions[last.id]=last.previous;else delete decisions[last.id];save();render();announce('Last choice undone. Notes kept.');});
function clearList(type){
 if(busy || !['good','bad'].includes(type) || !Object.values(decisions).includes(type))return;
 if(!confirm(`Clear your entire ${type} list? These schools will return to the review deck. Your other list and all notes will be kept.`))return;
 resetDrag();
 const clearedIds=new Set(Object.keys(decisions).filter(id=>decisions[id]===type));
 for(const id of clearedIds)delete decisions[id];
 // Older undo actions must not restore decisions that were deliberately cleared.
 history=history.filter(entry=>!clearedIds.has(entry.id));
 save();render();announce(`${type==='good'?'Good':'Bad'} list cleared. Other list and notes kept. Current search and filters still apply.`);
}
function clearNotes(){
 if(busy || !Object.keys(notes).length)return;
 if(!confirm('Delete all university notes, including notes on schools outside your lists? This cannot be undone. Your good and bad lists will be kept.'))return;
 notes={};editingNoteId=null;
 save();render();get('note').value='';
 announce('All university notes cleared. Both lists kept.');
}
get('clear-good').addEventListener('click',()=>clearList('good'));
get('clear-bad').addEventListener('click',()=>clearList('bad'));
get('clear-notes').addEventListener('click',clearNotes);
get('reset').addEventListener('click',()=>{if(busy || !confirm('Clear both lists and start reviewing again? Your university notes will be kept.'))return;decisions={};history=[];save();render();announce('Lists cleared. Notes kept.');});
get('note').addEventListener('input',event=>{if(currentSchool && !busy)storeNote(currentSchool.id,event.target.value);});
document.querySelector('.notebook').addEventListener('toggle',event=>{
 const active=document.activeElement;
 if(event.target.open && !(active?.matches('textarea[data-school-id]') && event.target.contains(active)))renderNotebook();
});
function resetFilters(){
 get('search').value='';get('field').value='';get('size-enabled').checked=false;get('size-max').value='10000';get('tuition-basis').value='tuitionOut';get('include-unknown').checked=false;
 for(const id of ['citations','employment','average-salary','international'])get(id).value='';
 for(const id of ['tuition','living']){get(id).value='10000';get(`${id}-enabled`).checked=false;}
 updateFilters();
}
function updateFilters(changed){
 if(busy)return;
 get('size-max-value').value=`Up to ${number(get('size-max').value)}`;
 for(const id of ['tuition','living'])get(`${id}-value`).value=`Up to ${money(Number(get(id).value))}`;
 resetDrag();renderCard();
}
get('filters').addEventListener('submit',event=>event.preventDefault());
get('filters').addEventListener('input',event=>updateFilters(event.target.id));
get('filters').addEventListener('reset',event=>{event.preventDefault();if(!busy)resetFilters();});
get('search').addEventListener('input',()=>updateFilters());
get('clear-search').addEventListener('click',()=>{get('search').value='';updateFilters();get('search').focus();});
get('reset-empty').addEventListener('click',resetFilters);
function exportData(){return {exportedAt:new Date().toISOString(),dataRelease:dataInfo.scorecardRelease,good:universities.filter(u=>decisions[u.id]==='good').map(u=>({id:u.id,name:u.name,url:u.url,note:notes[u.id] || ''})),bad:universities.filter(u=>decisions[u.id]==='bad').map(u=>({id:u.id,name:u.name,url:u.url,note:notes[u.id] || ''})),notes:universities.filter(u=>notes[u.id]?.trim()).map(u=>({id:u.id,name:u.name,note:notes[u.id]}))};}
get('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='university-choices-and-notes.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.addEventListener('keydown',event=>{
 if(get('auth-dialog').open)return;
 if(busy || drag || event.repeat || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || event.target.isContentEditable || ['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName))return;
 if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();choose(event.key==='ArrowLeft'?'bad':'good');}
});
for(const [code,label] of Object.entries(fieldNames).sort((a,b)=>a[1].localeCompare(b[1]))){const option=document.createElement('option');option.value=code;option.textContent=label;get('field').append(option);}
get('directory-count').textContent=`${number(universities.length)} U.S. institutions. Find your fit, save your choices, and keep your notes.`;
get('coverage').textContent=`${number(universities.length)} institutions. ${dataInfo.scope} Research counts available for ${number(dataInfo.citationCoverage)} schools; images for ${number(dataInfo.photoCoverage)} (${number(dataInfo.campusPhotoCoverage)} campus images and ${number(dataInfo.logoCoverage)} labeled emblems). School data retrieved ${dataInfo.retrieved}; images updated ${dataInfo.photosUpdated}.`;
if(matchMedia('(max-width: 800px)').matches)document.querySelector('.advanced').open=false;
render();



// Demonstration UI only: no authentication backend and no password persistence.
const demoSessionKey='university-demo-session-v1';
let authMode='signin';
let demoSession=null;
try {
 const stored=JSON.parse(sessionStorage.getItem(demoSessionKey) || 'null');
 if(stored && typeof stored.displayName==='string' && stored.displayName.trim())demoSession={displayName:stored.displayName.slice(0,60)};
} catch { /* The demonstration still works without session storage. */ }
function renderDemoSession() {
 get('guest-actions').hidden=!!demoSession;get('demo-account').hidden=!demoSession;
 get('demo-name').textContent=demoSession?`Demo: ${demoSession.displayName}`:'';
}
function clearAuthFields(){
 get('auth-form').reset();get('auth-password').type='password';get('auth-confirm').type='password';
 get('toggle-password').textContent='Show';get('toggle-password').setAttribute('aria-pressed','false');get('toggle-password').setAttribute('aria-label','Show demo passwords');
 get('auth-confirm').setCustomValidity('');get('auth-name').setCustomValidity('');get('auth-password').setCustomValidity('');get('auth-error').textContent='';
}
function setAuthMode(mode){
 authMode=mode;clearAuthFields();const signup=mode==='signup';
 get('name-group').hidden=!signup;get('confirm-group').hidden=!signup;
 get('auth-name').required=signup;get('auth-confirm').required=signup;
 get('auth-title').textContent=signup?'Start your next chapter.':'Welcome back.';
 get('auth-subtitle').textContent=signup?'Preview creating a university shortlist account.':'Try the sign-in experience.';
 get('auth-submit').textContent=signup?'Try demo sign-up':'Try demo sign-in';
 get('signin-mode').setAttribute('aria-pressed',String(!signup));get('signup-mode').setAttribute('aria-pressed',String(signup));
}
function openAuth(mode){setAuthMode(mode);get('auth-dialog').showModal();get(mode==='signup'?'auth-name':'auth-email').focus();}
get('open-signin').addEventListener('click',()=>openAuth('signin'));
get('open-signup').addEventListener('click',()=>openAuth('signup'));
get('signin-mode').addEventListener('click',()=>{setAuthMode('signin');get('auth-email').focus();});
get('signup-mode').addEventListener('click',()=>{setAuthMode('signup');get('auth-name').focus();});
get('close-auth').addEventListener('click',()=>get('auth-dialog').close());
get('continue-guest').addEventListener('click',()=>get('auth-dialog').close());
get('auth-dialog').addEventListener('close',clearAuthFields);
get('auth-form').addEventListener('input',()=>{get('auth-confirm').setCustomValidity('');get('auth-name').setCustomValidity('');get('auth-password').setCustomValidity('');get('auth-error').textContent='';});
get('toggle-password').addEventListener('click',()=>{
 const show=get('auth-password').type==='password';get('auth-password').type=show?'text':'password';get('auth-confirm').type=show?'text':'password';
 get('toggle-password').textContent=show?'Hide':'Show';get('toggle-password').setAttribute('aria-pressed',String(show));get('toggle-password').setAttribute('aria-label',show?'Hide demo passwords':'Show demo passwords');
});
get('auth-form').addEventListener('submit',event=>{
 event.preventDefault();get('auth-error').textContent='';
 const signup=authMode==='signup';
 if(get('auth-password').value.length<8){get('auth-password').setCustomValidity('Use at least 8 characters for the demo password.');get('auth-error').textContent='Use at least 8 characters for the demo password.';}
 if(signup && !get('auth-name').value.trim())get('auth-name').setCustomValidity('Enter a demo display name.');
 if(signup && get('auth-password').value!==get('auth-confirm').value){get('auth-confirm').setCustomValidity('The demo passwords must match.');get('auth-error').textContent='The demo passwords must match.';}
 if(!get('auth-form').reportValidity())return;
 const displayName=(signup?get('auth-name').value.trim():get('auth-email').value.split('@')[0]).slice(0,60);
 demoSession={displayName};
 try {sessionStorage.setItem(demoSessionKey,JSON.stringify(demoSession));} catch { /* Memory-only demo session. */ }
 clearAuthFields();get('auth-dialog').close();renderDemoSession();
 get('account-status').textContent=`Demo ${signup?'sign-up':'sign-in'} complete. No real account was created or verified. Your lists and notes remain in this browser.`;
 get('signout').focus();
});
get('signout').addEventListener('click',()=>{
 demoSession=null;try {sessionStorage.removeItem(demoSessionKey);} catch { /* Nothing persisted. */ }
 renderDemoSession();get('account-status').textContent='Demo signed out. Your university lists and notes are still saved in this browser.';get('open-signin').focus();
});
renderDemoSession();
